@RequestMapping("/file/file")
public class FileController {

    private static final Logger log = LoggerFactory.getLogger(FileController.class);

    @Autowired
    private FileService fileService;

    @Autowired
    private FilePreviewService filePreviewService;

    @Autowired
    private RedisService redisService;

    /**
     * 文件鉴权预览（MinIO 鉴权改造）：桶收匿名读后的统一读文件通道。
     * 鉴权：不加网关白名单 = 强制登录；img/window.open 场景由前端在 query 上带 ?token=[REDACTED]
     */
    @GetMapping("/preview")
    public void preview(@RequestParam String path,
                        @RequestParam(value = "name", required = false) String name,
                        HttpServletRequest request, HttpServletResponse response) throws java.io.IOException {
        filePreviewService.writePreview(path, name, request, response);
    }

    /**
     * 匿名票据预览（企业/机构注册等未登录流程专用）：票据由 uploadAnonymous /
     * getAnonymousPreviewTickets 签发，短时效且与 path 绑定；需在网关白名单放行本端点。
     */
    @GetMapping("/previewByTicket")
    public void previewByTicket(@RequestParam String path,
                                @RequestParam String ticket,
                                HttpServletRequest request, HttpServletResponse response) throws java.io.IOException {
        Object bound = redisService.getCacheObject(FileConstants.PREVIEW_TICKET_KEY_PREFIX + ticket);
        // path 绑定校验：原图一致，或绑定原图行的派生缩略图（大图上传生成 _s 缩略图，
        // 组件回显请求的是 fileThumbnailSite，严格一对一绑定会把合法回显 401）
        if (bound == null || !filePreviewService.isTicketBoundPath(String.valueOf(bound), path)) {
            response.sendError(HttpServletResponse.SC_UNAUTHORIZED, "预览票据无效或已过期");
            return;
        }
        filePreviewService.writePreview(path, null, request, response);
    }

    /**
     * 平台配置图公共输出（登录页等匿名场景的品牌图）：服务端仅放行 sys_platform_config
     * 图片字段（sysLogo/背景图/登录框图/政网站点徽标等）精确登记的路径，业务附件一律 404。
     * 需在网关白名单放行本端点。
     */
    @GetMapping("/previewPublicConfig")
    public void previewPublicConfig(@RequestParam String path,
                                    HttpServletRequest request, HttpServletResponse response) throws java.io.IOException {
        filePreviewService.writePublicConfigPreview(path, request, response);
    }

    /**
     * 文件上传请求
     */
    @PostMapping("upload")
    public JsonResult<FileVo> upload(MultipartFile file) {
        if (file.isEmpty() || ObjectUtil.isEmpty(file.getOriginalFilename())) {
            return JsonResult.fail("上传文件异常，请联系管理员");
        }
//        if (FileConstants.FILE_NAME_MAX_LENGTH < file.getOriginalFilename().length()) {
//            throw new ServiceException("文件上传失败，文件名过长，请修改文件名后重新上传！");
//        }
        try {
            // 上传并返回访问地址
            FileVo fileVo = fileService.upload(file);
            if (ObjectUtil.isEmpty(fileVo) || StrUtil.isBlank(fileVo.getFileSite())) {
                return JsonResult.fail("文件服务异常，请联系管理员");
            }
            return JsonResult.success(fileVo);
        } catch (Exception e) {
            log.error("上传文件失败", e);
"}]

